-- Airlinerra German expansion paved runway Batch 02, 2026-10-26.
-- SOURCE: current airfield operator, operator-hosted aviation regulation, municipal operator report, or secondary/historical source for the held records.
-- Research only: DO NOT activate airports or assert any commercial aircraft/airline authorizations.
-- PREREQUISITE schema created in Batch 01:
-- docs/sql/AIRLINERRA_EXPANSION_DE_INDEPENDENT_RUNWAY_BATCH_01_2026-10-26.sql
DO $check$ BEGIN
 IF (SELECT count(*) FROM airlinerra.airport_world_activation WHERE world_number=1 AND active)<>3140
 OR EXISTS(SELECT 1 FROM airlinerra.airport_world_activation WHERE world_number<>1)
 THEN RAISE EXCEPTION 'Foundation release changed; abort German expansion Batch 02'; END IF;
END $check$;

