UPDATE airlinerra.airport_access_reviews a SET
 identity_status='VERIFIED',paved_runway_status='VERIFIED',
 review_status='INDEPENDENT_OPERATOR_PAVED_RUNWAY_VERIFIED_SIMULATION_RELEASE_PENDING',
 evidence_url=r.source_url,
 source_review_note='2026-10-26 independent German runway review Batch 02: operator-source paved runway confirmed, no game/commercial admission. ' || r.evidence_notes || ' Next: ' || r.next_review_action,
 review_date='2026-10-26',last_updated=now()
FROM airlinerra.airport_expansion_independent_paved_runway_reviews r
JOIN airlinerra.airport_cohorts cohort ON cohort.airport_key=r.airport_key AND cohort.cohort='EXPANSION_3906'
WHERE a.airport_key=r.airport_key
 AND r.batch_key='EXPANSION_DE_PAVED_BATCH_02_2026_10_26'
 AND r.source_authority_grade='CURRENT_AIRPORT_OPERATOR'
 AND a.review_status='HOLD_INDEPENDENT_VERIFICATION'
 AND a.game_admission_status='NOT_APPROVED';

SELECT icao_code,research_status,paved_runway_pair,documented_physical_length_m,published_landing_direction_a_m,published_landing_direction_b_m
FROM airlinerra.airport_expansion_independent_paved_runway_reviews
WHERE batch_key='EXPANSION_DE_PAVED_BATCH_02_2026_10_26' ORDER BY icao_code;
